import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Grave } from '../types'
import { epitaphFor } from './epitaph'
import { rmTargets } from './rm'

const PANE = 'graveyard'
const graves = atom({ plugin: 'graveyard', key: 'graves' } as const, [])

const STONE_WIDTH = 22
const MAX_RECURSIVE = 200

type $ = EngineInterface

const run = async ($: $, argv: string[], cwd?: string) => {
  const ran = await $.process
    .run(argv, { cwd, timeoutMs: 5000 })
    .catch(() => undefined)
  return ran?.exitCode === 0 ? ran.stdout : undefined
}

const join = (dir: string, path: string) =>
  path.startsWith('/') ? path : `${dir.replace(/\/$/, '')}/${path}`

const dirOf = (path: string) => path.slice(0, path.lastIndexOf('/')) || '/'
const baseOf = (path: string) => path.slice(path.lastIndexOf('/') + 1)

// Everything known about a file, read before it dies; undefined when it is
// not a regular file. Nothing is copied: a file git knows can be raised
// from its last commit, any other stays gone.
const exhume = async ($: $, path: string): Promise<Grave | undefined> => {
  const stat = await $.fs.stat(path).catch(() => undefined)
  if (stat?.kind !== 'file') return undefined

  const id = `${await $.clock.now()}-${Math.random().toString(36).slice(2, 8)}`
  const name = baseOf(path)
  const wc = await run($, ['wc', '-l', path])
  const cwd = dirOf(path)
  const tracked = (await run($, ['git', 'ls-files', '--full-name', '--', name], cwd))?.trim()
  const repo = tracked ? (await run($, ['git', 'rev-parse', '--show-toplevel'], cwd))?.trim() : undefined
  const log = tracked ? await run($, ['git', 'log', '--format=%H %cI', '--', name], cwd) : undefined
  const commits = (log ?? '').split('\n').filter(Boolean).map(line => line.split(' '))
  const [commit, lastCommit = null] = commits[0] ?? []
  const firstCommit = commits[commits.length - 1]?.[1]
  const git = tracked && repo && commit ? { repo, path: tracked, commit } : null
  const bornYear = firstCommit
    ? Number(firstCommit.slice(0, 4))
    : stat.mtimeMs > 0
      ? new Date(stat.mtimeMs).getFullYear()
      : null

  return {
    id,
    path,
    name,
    lines: Number((wc ?? '').trim().split(/\s+/)[0]) || 0,
    bytes: stat.size,
    bornYear,
    lastCommit,
    diedAt: await $.clock.now(),
    epitaph: epitaphFor(name),
    git,
    isRisen: false,
  }
}

// A tool call that will delete files: bury them first, let it run untouched,
// then un-bury any that survived it.
const witness = async (
  $: $,
  paths: string[],
  stillAlive: (path: string) => Promise<boolean>,
) => {
  const buried: Grave[] = []
  for (const path of paths) {
    const grave = await exhume($, path).catch(() => undefined)
    if (grave) buried.push(grave)
  }
  return async () => {
    const dead: Grave[] = []
    for (const grave of buried) {
      if (!(await stillAlive(grave.path))) dead.push(grave)
    }
    if (dead.length > 0) await update($, graves, list => [...list, ...dead])
  }
}

const expandRecursive = async ($: $, path: string) => {
  const stat = await $.fs.stat(path).catch(() => undefined)
  if (stat?.kind === 'file') return [path]
  if (stat?.kind !== 'dir') return []
  const found = await run($, ['find', path, '-type', 'f'])
  return (found ?? '').split('\n').filter(Boolean).slice(0, MAX_RECURSIVE)
}

const pad = (text: string, width: number) => {
  const cut = text.length > width ? `${text.slice(0, width - 1)}~` : text
  const left = Math.floor((width - cut.length) / 2)
  return ' '.repeat(left) + cut + ' '.repeat(width - cut.length - left)
}

const wrap = (text: string, width: number, rows: number) => {
  const out: string[] = []
  let line = ''
  for (const word of text.split(' ')) {
    if (line && line.length + 1 + word.length > width) {
      out.push(line)
      line = word
    } else {
      line = line ? `${line} ${word}` : word
    }
  }
  if (line) out.push(line)
  if (out.length > rows) {
    out.length = rows
    out[rows - 1] = `${(out[rows - 1] ?? '').slice(0, width - 3)}...`
  }
  while (out.length < rows) out.push('')
  return out
}

const tombstone = (grave: Grave) => {
  const inner = STONE_WIDTH - 4
  const died = new Date(grave.diedAt).getFullYear()
  const years = `${grave.bornYear ?? '?'} - ${died}`
  const body = [
    grave.isRisen ? 'RISEN' : 'here lies',
    grave.name,
    `${grave.lines} lines`,
    years,
    '',
    ...wrap(grave.epitaph, inner, 3),
  ]
  return [
    `    .${'-'.repeat(STONE_WIDTH - 10)}.    `,
    `  .'${' '.repeat(STONE_WIDTH - 8)}'.  `,
    ` / ${pad(grave.isRisen ? ' ' : '+', inner)} \\ `,
    ...body.map(row => ` | ${pad(row, inner)} | `),
    `_|${'_'.repeat(inner + 2)}|_`,
  ]
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'graveyard',
      description: 'Visit the tombstones of every file deleted this session',
    })
    await $.command.register({
      name: 'seance',
      description: 'Raise a deleted file from its last git commit',
      argumentHint: '<file>',
    })
    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const root = await $.session.root()
    const home = (await $.env.get('HOME')) ?? ''
    const paths: string[] = []
    for (const target of rmTargets(e.command)) {
      const cwd = target.cwd ? join(root, target.cwd) : root
      const path = join(cwd, target.path.replace(/^~(?=\/|$)/, home))
      paths.push(...(target.isRecursive ? await expandRecursive($, path) : [path]))
    }
    if (paths.length === 0) return next(e)

    const settle = await witness($, paths, path => $.fs.exists(path))
    const ran = await next(e)
    await settle()
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const before = await $.fs.read(e.file_path).catch(() => '')
    if (e.content.trim() !== '' || before.trim() === '') return next(e)

    const settle = await witness($, [e.file_path], async path =>
      ((await $.fs.read(path).catch(() => '')) as string).trim() !== '',
    )
    const ran = await next(e)
    await settle()
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const before = await $.fs.read(e.file_path).catch(() => '')
    const after = e.replace_all
      ? before.split(e.old_string).join(e.new_string)
      : before.replace(e.old_string, () => e.new_string)
    if (before.trim() === '' || after.trim() !== '') return next(e)

    const settle = await witness($, [e.file_path], async path =>
      ((await $.fs.read(path).catch(() => '')) as string).trim() !== '',
    )
    const ran = await next(e)
    await settle()
    return ran
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'graveyard' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Graveyard' })
    const count = (await read($, graves)).length
    return { text: count === 0 ? 'The graveyard is empty. For now.' : 'The gates creak open.' }
  })

  on('command.run', { command: 'seance' }, async ($, e) => {
    const wanted = e.args.trim()
    if (wanted === '') return { text: 'Usage: /seance <file>' }

    const root = await $.session.root()
    const full = join(root, wanted)
    const list = await read($, graves)
    const grave = [...list]
      .reverse()
      .find(one => !one.isRisen && (one.path === full || one.path === wanted || one.name === wanted))
    if (!grave) return { text: `No spirit named ${wanted} answers.` }

    const { git } = grave
    if (!git) {
      return { text: `${grave.name} was never committed. It is gone for good.` }
    }
    const living = await $.fs.read(grave.path).catch(() => '')
    if (living.trim() !== '') {
      return { text: `Something already haunts ${grave.path}; the seance is called off.` }
    }

    const restored = await run(
      $,
      ['git', 'restore', `--source=${git.commit}`, '--worktree', '--', git.path],
      git.repo,
    )
    if (restored === undefined) return { text: `The spirit of ${grave.name} would not cross over.` }

    await update($, graves, all =>
      all.map(one => (one.id === grave.id ? { ...one, isRisen: true } : one)),
    )
    $.ui.toast(`the spirit of ${grave.name} returns`)
    return { text: `Restored ${grave.path} as of commit ${git.commit.slice(0, 7)}` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const list = await read($, graves)
    if (list.length === 0) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No one has died yet. The ground is fresh.</Text>
        </Box>
      )
    }

    const columns = e.viewport?.columns ?? 80
    const perRow = Math.max(1, Math.floor((columns - 2) / (STONE_WIDTH + 1)))
    const rows: Grave[][] = []
    for (let i = 0; i < list.length; i += perRow) rows.push(list.slice(i, i + perRow))

    return (
      <Box flexDirection="column">
        <Text dimColor>
          {list.length} buried, {list.filter(one => one.isRisen).length} risen. /seance {'<file>'} to raise one.
        </Text>
        {rows.map((row, r) => {
          const stones = row.map(tombstone)
          return (
            <Box key={`row-${r}`} flexDirection="column" marginTop={1}>
              {(stones[0] ?? []).map((_, line) => (
                <Text key={`l-${r}-${line}`} wrap="truncate-end">
                  {stones.map(stone => stone[line]).join(' ')}
                </Text>
              ))}
              <Text dimColor wrap="truncate-end">
                {'~'.repeat(Math.min(columns - 2, row.length * (STONE_WIDTH + 1)))}
              </Text>
            </Box>
          )
        })}
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const count = (await read($, graves)).length
    if (count === 0 || e.props.hasSurvey) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box>
        <Text dimColor>⚰ {count} buried this session</Text>
      </Box>
    )
  })
}

