export type RmTarget = { path: string; cwd?: string; isRecursive: boolean }

const OPERATORS = new Set([';', '&&', '||', '|', '&', '\n'])

// Splits a shell command into words and operators, honouring quotes and
// backslashes; a word that held a glob outside quotes keeps `isGlob`.
const tokenize = (command: string) => {
  const tokens: { text: string; isOperator: boolean; isGlob: boolean }[] = []
  let word = ''
  let isWord = false
  let isGlob = false
  const flush = () => {
    if (isWord) tokens.push({ text: word, isOperator: false, isGlob })
    word = ''
    isWord = false
    isGlob = false
  }
  for (let i = 0; i < command.length; i++) {
    const c = command[i] ?? ''
    const pair = command.slice(i, i + 2)
    if (c === "'") {
      const end = command.indexOf("'", i + 1)
      word += command.slice(i + 1, end < 0 ? undefined : end)
      isWord = true
      i = end < 0 ? command.length : end
    } else if (c === '"') {
      let j = i + 1
      while (j < command.length && command[j] !== '"') {
        if (command[j] === '\\' && j + 1 < command.length) j++
        word += command[j] ?? ''
        j++
      }
      isWord = true
      i = j
    } else if (c === '\\' && i + 1 < command.length) {
      word += command[++i] ?? ''
      isWord = true
    } else if (pair === '&&' || pair === '||') {
      flush()
      tokens.push({ text: pair, isOperator: true, isGlob: false })
      i++
    } else if (OPERATORS.has(c)) {
      flush()
      tokens.push({ text: c, isOperator: true, isGlob: false })
    } else if (c === ' ' || c === '\t') {
      flush()
    } else {
      if (c === '*' || c === '?' || c === '[') isGlob = true
      word += c
      isWord = true
    }
  }
  flush()
  return tokens
}

// The files and folders each `rm` in a command names, with the folder a
// preceding `cd` in the same command moved to. Globs and `$` expansions are
// skipped: what they name is unknown until the shell runs.
export const rmTargets = (command: string): RmTarget[] => {
  const targets: RmTarget[] = []
  let cwd: string | undefined
  let words: { text: string; isGlob: boolean }[] = []

  const segment = () => {
    let i = 0
    while (/^\w+=/.test(words[i]?.text ?? '')) i++
    if (words[i]?.text === 'sudo' || words[i]?.text === 'command') i++
    const head = words[i]?.text ?? ''
    if (head === 'cd' && words[i + 1]) {
      const to = words[i + 1]?.text ?? '.'
      cwd = to.startsWith('/') || cwd === undefined ? to : `${cwd}/${to}`
    }
    if (head === 'rm' || head.endsWith('/rm')) {
      let isRecursive = false
      let isOptions = true
      const paths: string[] = []
      for (const word of words.slice(i + 1)) {
        if (isOptions && word.text === '--') {
          isOptions = false
        } else if (isOptions && /^-[a-zA-Z]+$/.test(word.text)) {
          if (/[rR]/.test(word.text)) isRecursive = true
        } else if (isOptions && /^--recursive$/.test(word.text)) {
          isRecursive = true
        } else if (isOptions && word.text.startsWith('--')) {
          // another long option
        } else if (!word.isGlob && !word.text.includes('$') && word.text !== '') {
          paths.push(word.text)
        }
      }
      for (const path of paths) targets.push({ path, cwd, isRecursive })
    }
    words = []
  }

  for (const token of tokenize(command)) {
    if (token.isOperator) segment()
    else words.push(token)
  }
  segment()
  return targets
}

