// Where git last held a dead file: the repository, the file's path in it,
// and the last commit that touched it. Null for a file git never tracked.
export type GraveGit = { repo: string; path: string; commit: string }

export type Grave = {
  id: string
  path: string
  name: string
  lines: number
  bytes: number
  bornYear: number | null
  lastCommit: string | null
  diedAt: number
  epitaph: string
  git: GraveGit | null
  isRisen: boolean
}

declare module 'claude-code' {
  interface PluginState {
    graveyard: { graves: Grave[] }
  }
}
